def with_retries(max_attempts=3, backoff_factor=2, initial_delay=1):
    """Decorator that retries a function on exception with exponential backoff and jitter.

    Args:
        max_attempts: Maximum number of attempts before raising the exception.
        backoff_factor: Multiplier for delay between retries.
        initial_delay: Initial delay in seconds before first retry.

    Returns:
        Decorated function that retries on exceptions (except KeyboardInterrupt, SystemExit).
